// Get the Vertex AI response
const items = $input.all();

return items.map(item => {
  const response = item.json.candidates[0].content.parts[0].text;

  // Strip markdown code blocks if present
  let cleanJson = response.trim();
  if (cleanJson.startsWith('```json')) {
    cleanJson = cleanJson.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  }

  // Parse the JSON
  const parsed = JSON.parse(cleanJson);

  // Return as ONE ITEM with analysis as nested array
  return {
    json: {
      overall_review: parsed.overall_review,
      analysis: parsed.analysis, // Keep as array
      transcript: parsed.transcript
    }
  };
});

